import { createHash, randomBytes } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { sql } from 'drizzle-orm';
import { hasUsers, type Database } from '@platform/db';

/**
 * Deployment secrets that may be left unset: each is resolved, in order, from
 *   1. the environment (an explicit value always wins and is never written anywhere),
 *   2. `<DATA_DIR>/secrets/<NAME>` (generated by an earlier start),
 *   3. a freshly generated random value, persisted there with mode 0600.
 * Step 3 only happens when replacing the value cannot lose anything: the three core keys are
 * generated only while the database has no accounts, and no key is ever generated once this
 * database has recorded a fingerprint for it. Every start then compares the resolved value
 * with that fingerprint, so a changed key (or a second instance with its own generated keys)
 * stops startup instead of invalidating sessions or making encrypted data unreadable.
 */
export const generatedSecrets = [
  // Better Auth signing secret (sessions, OAuth tokens in the account table).
  { name: 'BETTER_AUTH_SECRET', generate: () => randomBytes(32).toString('hex'), core: true },
  // MCP/OAuth credential vault.
  { name: 'ENCRYPTION_KEY', generate: () => randomBytes(32).toString('base64'), core: true },
  // Device authorization HMAC master key.
  {
    name: 'DEVICE_AUTH_ENCRYPTION_KEY',
    generate: () => randomBytes(32).toString('base64'),
    core: true,
  },
  // Pi MCP adapter OAuth file key: only encrypts files that cannot exist without it.
  {
    name: 'PI_MCP_ADAPTER_OAUTH_FILE_KEY',
    generate: () => randomBytes(32).toString('base64'),
    core: false,
  },
] as const;
export type SecretName = (typeof generatedSecrets)[number]['name'];
export type SecretSource = 'env' | 'file' | 'generated';

export class SecretError extends Error {
  override name = 'SecretError';
}

/** What the resolver needs from the database; the real one is `databaseSecretStore`. */
export type SecretStore = {
  hasUsers(): Promise<boolean>;
  fingerprint(name: SecretName): Promise<string | undefined>;
  /** Records `fingerprint` unless one exists; returns the stored fingerprint either way. */
  record(name: SecretName, fingerprint: string): Promise<string>;
};

export function databaseSecretStore(db: Database): SecretStore {
  return {
    hasUsers: () => hasUsers(db),
    async fingerprint(name) {
      const result = await db.execute<{ fingerprint: string }>(
        sql`select "fingerprint" from "deployment_secrets" where "name" = ${name}`,
      );
      return result.rows[0]?.fingerprint;
    },
    async record(name, fingerprint) {
      await db.execute(
        sql`insert into "deployment_secrets" ("name", "fingerprint") values (${name}, ${fingerprint}) on conflict ("name") do nothing`,
      );
      const stored = await this.fingerprint(name);
      if (!stored) throw new SecretError(`无法记录 ${name} 的指纹`);
      return stored;
    },
  };
}

/** One-way, name-scoped fingerprint; the value itself never reaches the database. */
export const secretFingerprint = (name: SecretName, value: string) =>
  createHash('sha256').update(`mcp-platform/deployment-secret/${name}\0${value}`).digest('hex');

export type ResolvedSecret = { name: SecretName; source: SecretSource; path?: string };

export async function resolveSecrets(options: {
  env: Record<string, string | undefined>;
  dataDir: string;
  store: SecretStore;
  /** AUTO_GENERATE_SECRETS=false turns step 3 off (values must then come from env or files). */
  generate: boolean;
  log?: (message: string) => void;
}): Promise<{ values: Record<SecretName, string>; resolved: ResolvedSecret[] }> {
  const directory = join(options.dataDir, 'secrets');
  const values = {} as Record<SecretName, string>;
  const resolved: ResolvedSecret[] = [];
  for (const spec of generatedSecrets) {
    const path = join(directory, spec.name);
    const explicit = options.env[spec.name]?.trim() || undefined;
    let value: string;
    let source: SecretSource;
    if (explicit) {
      value = explicit;
      source = 'env';
    } else {
      const stored = await readSecret(path);
      if (stored) {
        value = stored;
        source = 'file';
      } else {
        await mayGenerate(spec, options);
        const written = await persist(path, spec.generate(), spec.name);
        value = written.value;
        source = written.created ? 'generated' : 'file';
        if (written.created)
          options.log?.(
            `已自动生成 ${spec.name} 并保存到 ${path}（权限 0600）。请把它和数据库一起备份；丢失后已登录会话或加密数据将无法恢复。`,
          );
      }
    }
    await checkFingerprint(spec.name, value, source, path, options.store);
    values[spec.name] = value;
    resolved.push({ name: spec.name, source, ...(source === 'env' ? {} : { path }) });
  }
  return { values, resolved };
}

async function mayGenerate(
  spec: (typeof generatedSecrets)[number],
  options: { generate: boolean; store: SecretStore },
) {
  const restore = `请设置环境变量 ${spec.name}，或把原来的值放回 DATA_DIR/secrets/${spec.name}`;
  if (!options.generate)
    throw new SecretError(`缺少 ${spec.name}，且 AUTO_GENERATE_SECRETS=false。${restore}。`);
  if (await options.store.fingerprint(spec.name))
    throw new SecretError(
      `缺少 ${spec.name}，但这个数据库已经用过它。拒绝生成新值（会让会话失效或已加密的数据无法解密）。${restore}；多实例部署时所有实例必须使用同一个值。`,
    );
  if (spec.core && (await options.store.hasUsers()))
    throw new SecretError(
      `缺少 ${spec.name}，但数据库里已有账号。拒绝生成新值（会让会话失效或已加密的数据无法解密）。${restore}。`,
    );
}

async function readSecret(path: string) {
  try {
    return (await readFile(path, 'utf8')).trim() || undefined;
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code;
    if (code === 'ENOENT' || code === 'ENOTDIR') return undefined;
    throw new SecretError(
      `无法读取 ${path}：${(error as Error).message}。请确认运行平台的用户能读这个文件。`,
      { cause: error },
    );
  }
}

/** Exclusive create: when two processes start at once, the loser reads the winner's value. */
async function persist(path: string, value: string, name: SecretName) {
  try {
    await mkdir(join(path, '..'), { recursive: true, mode: 0o700 });
    await writeFile(path, `${value}\n`, { mode: 0o600, flag: 'wx' });
    return { value, created: true };
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'EEXIST') {
      const existing = await readSecret(path);
      if (existing) return { value: existing, created: false };
    }
    throw new SecretError(
      `无法把自动生成的 ${name} 写入 ${path}：${(error as Error).message}。请让 DATA_DIR 可写（Docker 里挂载 /app/.data 数据卷），或显式设置环境变量 ${name}。`,
      { cause: error },
    );
  }
}

async function checkFingerprint(
  name: SecretName,
  value: string,
  source: SecretSource,
  path: string,
  store: SecretStore,
) {
  const stored = await store.record(name, secretFingerprint(name, value));
  if (stored === secretFingerprint(name, value)) return;
  const from = source === 'env' ? `环境变量 ${name}` : path;
  throw new SecretError(
    `${name}（来自 ${from}）和这个数据库第一次使用的值不一致，拒绝启动以免会话失效或加密数据无法解密。` +
      `常见原因：多个实例没有共享同一个 DATA_DIR/secrets（或同一组环境变量），各自生成了不同的密钥；或者 .env 里的值被改过、数据卷被换掉。` +
      `请改回原来的值；确实要轮换密钥时，先按 docs/deployment.md 的说明处理。`,
  );
}
